-- New versus returning customer orders by month.
WITH x AS (SELECT customer_unique_id,date_trunc('month',order_purchase_timestamp)::date AS month_start,MIN(date_trunc('month',order_purchase_timestamp)::date) OVER(PARTITION BY customer_unique_id) AS cohort FROM analytics.v_order_value WHERE order_status='delivered') SELECT month_start,COUNT(*) FILTER(WHERE month_start=cohort) AS new_orders,COUNT(*) FILTER(WHERE month_start>cohort) AS returning_orders FROM x GROUP BY 1 ORDER BY 1;
